<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {use} from 'echarts/core';
import {PieChart} from 'echarts/charts';
import {TooltipComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
import VChart from 'vue-echarts';
use([PieChart,TooltipComponent,CanvasRenderer]);
const props=defineProps<{department:{id:string|null,name:string},cycle:any,results:any[],participants:any[]|null}>();
const emit=defineEmits<{(e:'close'):void}>();
const tab=ref<'growth'|'members'>('growth');
const rows=computed(()=>props.results.filter(r=>r.department_id===props.department.id));
const members=computed(()=>props.participants?.filter(p=>p.dept_snapshot===props.department.id&&p.eligibility==='ELIGIBLE').slice().sort((a,b)=>String(a.display_name).localeCompare(String(b.display_name),'zh-CN-u-co-pinyin'))??[]);
const scores=computed(()=>rows.value.map(r=>r.payload_json?.final_score).filter(v=>v!=null&&Number.isFinite(Number(v))).map(Number));
const avg=computed(()=>scores.value.length?scores.value.reduce((a,b)=>a+b,0)/scores.value.length:null);
const dims=computed(()=>{const m=new Map<string,number[]>();for(const r of rows.value)for(const i of r.payload_json?.peer_items??[]){if(!i.label||i.avg_score==null||!Number.isFinite(Number(i.avg_score)))continue;const list=m.get(i.label)??[];list.push(Number(i.avg_score));m.set(i.label,list)}return [...m].map(([label,values])=>({label,score:values.reduce((a,b)=>a+b,0)/values.length}))});
const bands=[{label:'90–100 分',min:90,max:101,color:'#306cf4'},{label:'80–89 分',min:80,max:90,color:'#7aa7fa'},{label:'60–79 分',min:60,max:80,color:'#bed4fb'},{label:'0–59 分',min:0,max:60,color:'#ffa061'}];
const distribution=computed(()=>bands.map(b=>({...b,count:scores.value.filter(n=>n>=b.min&&n<b.max).length})));
const chart=computed(()=>({tooltip:{trigger:'item'},series:[{type:'pie',radius:['60%','80%'],label:{show:false},data:distribution.value.map(d=>({name:d.label,value:d.count,itemStyle:{color:d.color}}))}]}));
function key(e:KeyboardEvent){if(e.key==='Escape')emit('close')};onMounted(()=>window.addEventListener('keydown',key));onBeforeUnmount(()=>window.removeEventListener('keydown',key));
</script>
<template><Teleport to="body"><div class="shade" @click.self="emit('close')"><aside class="drawer" role="dialog" aria-modal="true" :aria-label="'部门成长报告 · '+department.name"><header><div><h2>部门成长报告 · {{department.name}}</h2><p>{{cycle?.month||'—'}} · 正式发布结果</p></div><button class="close" aria-label="关闭" @click="emit('close')">×</button></header><nav><button :class="{active:tab==='growth'}" @click="tab='growth'">成长分析</button><button :class="{active:tab==='members'}" @click="tab='members'">成员概况</button></nav><div class="body"><template v-if="tab==='growth'"><div class="metrics"><div><small>有效成绩人数</small><strong>{{scores.length}}</strong></div><div><small>有效他评平均分</small><strong>{{avg?.toFixed(2)??'—'}}</strong></div><div><small>有数据的评价维度</small><strong>{{dims.length||'—'}}</strong></div></div><p class="note">基于本部门有效参评成员的最新正式发布快照；先计算每位成员的他评均分，再计算部门均值。自评不计入。</p><section><h3>部门维度表现</h3><div v-for="d in dims" :key="d.label" class="dimension"><span>{{d.label}}</span><progress max="100" :value="d.score"/><b>{{d.score.toFixed(2)}}</b></div><p v-if="!dims.length" class="empty">暂无正式发布的维度数据</p></section><section><h3>成绩分布</h3><div v-if="scores.length" class="distribution"><VChart :option="chart" autoresize class="chart"/><div class="legend"><div v-for="b in distribution" :key="b.label"><i :style="{background:b.color}"/>{{b.label}} <span>{{b.count}} 人（{{(b.count/scores.length*100).toFixed(1)}}%）</span></div></div></div><p v-else class="empty">暂无有效成绩</p></section><section><h3>AI 成长分析</h3><p class="note">部门级 AI 分析尚未接入，暂无可展示的报告。</p><div class="ai-grid"><div v-for="label in ['主要优势','改进关注','改进建议']" :key="label"><h4>{{label}}</h4><p>暂无分析</p></div></div></section></template><template v-else><section><h3>成员概况 · {{department.name}}</h3><p v-if="participants===null" class="note">当前账号无权查看成员名单，或名单加载失败。</p><template v-else><p class="note">应参评 {{members.length}} 人；评价完成情况及成长反馈摘要暂未提供。</p><table><thead><tr><th>姓名</th><th>评价状态</th><th>成长反馈摘要</th></tr></thead><tbody><tr v-for="p in members" :key="p.user_id"><td>{{p.display_name}}</td><td>—</td><td>暂无可展示的摘要</td></tr></tbody></table><p v-if="!members.length" class="empty">本部门暂无有效参评成员</p></template></section></template></div></aside></div></Teleport></template>
<style scoped>
.shade{position:fixed;inset:0;z-index:1000;background:rgba(18,35,58,.35);display:flex;justify-content:flex-end}.drawer{width:min(60vw,1050px);height:100%;background:#f4f7fc;display:flex;flex-direction:column;box-shadow:-6px 0 22px #18283b24;color:#1b3153}.drawer header{display:flex;align-items:center;justify-content:space-between;padding:22px 26px 12px;background:#fff}.drawer h2{font-size:20px;margin:0}.drawer header p,.note{color:#72839b;font-size:13px;line-height:1.7}.drawer header p{margin:7px 0}.close{border:0;background:none;font-size:28px;color:#71819a;cursor:pointer}.drawer nav{background:#fff;display:flex;gap:26px;padding:0 26px;border-bottom:1px solid #e3ebf5}.drawer nav button{background:none;border:0;padding:12px 2px;color:#70819b;cursor:pointer}.drawer nav button.active{color:#246bfd;border-bottom:2px solid #246bfd;font-weight:600}.body{overflow-y:auto;padding:22px 26px;flex:1}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metrics>div,section{background:white;border:1px solid #e2eaf5;border-radius:10px;padding:18px}.metrics small{display:block;color:#70819b}.metrics strong{display:block;margin-top:8px;font-size:24px}section{margin-top:14px}section h3{font-size:16px;margin:0 0 16px}.dimension{display:flex;align-items:center;gap:14px;margin:14px 0;font-size:13px}.dimension span{width:90px}.dimension b{width:50px;text-align:right}progress{flex:1;height:8px;accent-color:#3370ff}.distribution{display:flex;align-items:center;gap:28px}.chart{width:180px;height:180px}.legend{flex:1}.legend div{display:flex;align-items:center;gap:8px;margin:12px 0;font-size:13px}.legend i{width:9px;height:9px;border-radius:50%}.legend span{margin-left:auto}.ai-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.ai-grid>div{background:#f7f9fc;border-radius:8px;padding:12px}.ai-grid h4{margin:0;color:#42689c}.ai-grid p,.empty{color:#8998ad;font-size:13px}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th,td{padding:12px;border-bottom:1px solid #eef2f7}th{background:#f4f7fc;color:#6c7e97}@media(max-width:850px){.drawer{width:100%}.metrics{grid-template-columns:1fr}.ai-grid{grid-template-columns:1fr}.distribution{flex-wrap:wrap}}
</style>

